WITH flattened AS (SELECT id, plan, currency, EXPLODE(discounts) AS element FROM price_tiers) SELECT currency, CASE WHEN element >= 75 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, PERCENTILE_APPROX(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles, PERCENTILE_APPROX(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles_2, SIZE(COLLECT_SET(currency)) AS num_currencies, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY SIZE(COLLECT_SET(currency)) DESC) AS num_currencies_percent_rank FROM flattened GROUP BY currency, CASE WHEN element >= 75 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY currency ASC NULLS FIRST;
